// The preview page's "What's new" in every language: the updates, newest first. See common.ts for the row format.
import type { Row } from "../../../games/rarefriends-realm/lang/table.ts";

const table: Readonly<Record<string, Row>> = {
  "The world runs much further west. Past Westmarch's end the West Road goes on into <b>Deep Westmarch</b>, a border nobody drew: the Kingdom of <b>Hollowmere</b>'s last post at Westwatch (Friendhollow's kingdom has a name now), the Stone Field where the first fighting was, ruins, deserters and a hollow in the cliffs with one way in. Behind the Drakespine stands <b>Raria</b>, a walled city round a palace, where Her Radiance <b>Queen Rara</b>, Keeper of the Wise Friend's Law, sits beside her small kind husband. Everything there is beautiful, orderly and polite, and the <b>Raria Royal Rangers</b> are behind every pillar. Nobody in Hollowmere can say where Raria came from.": [
    "世界ははるか西へと続いています。ウェストマーチの果てを越えると、西街道は<b>奥ウェストマーチ</b>へ。誰も引いたことのない国境です。Westwatch にある<b>ホロウミア</b>王国の最後の駐屯地 (フレンドホロウの王国にもついに名前がつきました)、最初の戦いがあった石の野、廃墟、脱走兵、そして入り口がひとつしかない崖のくぼみ。ドレイクスパインの向こうには、宮殿を囲む城壁の都<b>ラリア</b>がそびえ、賢き友の法の守護者たる光輝なる<b>女王ララ</b>が、小柄で優しい夫の隣に座しています。そこではすべてが美しく、秩序正しく、礼儀正しく、すべての柱の陰に<b>ラリア王立レンジャー</b>がいます。ラリアがどこから来たのか、ホロウミアの誰にもわかりません。",
    "세계는 훨씬 더 서쪽으로 이어집니다. 웨스트마치의 끝을 지나면 서쪽 길은 <b>깊은 웨스트마치</b>로, 아무도 그은 적 없는 국경으로 들어섭니다. Westwatch에 있는 <b>할로우미어</b> 왕국의 마지막 초소(프렌드할로우의 왕국에도 이제 이름이 생겼습니다), 첫 전투가 벌어진 돌의 들판, 폐허, 탈영병, 그리고 들어가는 길이 하나뿐인 절벽 속 우묵한 곳. 드레이크스파인 너머에는 궁전을 둘러싼 성벽 도시 <b>라리아</b>가 서 있고, 현명한 친구의 법의 수호자이신 빛나는 <b>라라 여왕</b>께서 작고 다정한 남편 곁에 앉아 계십니다. 그곳은 모든 것이 아름답고 질서 정연하며 예의 바르고, 모든 기둥 뒤에 <b>라리아 왕실 레인저단</b>가 있습니다. 라리아가 어디서 왔는지 할로우미어의 누구도 말하지 못합니다.",
    "世界向西延伸得更远了。越过西境的尽头，西路继续通往<b>西境深处</b>，一条从没人划定的边界：<b>虚湖</b>王国在 Westwatch 的最后一座哨所（友谷所在的王国终于有了名字）、最初交战的石原、废墟、逃兵，以及悬崖间只有一个入口的洼地。龙脊山之后矗立着<b>拉瑞亚</b>，一座环绕宫殿的城墙之城，贤友律法的守护者、光辉的<b>拉拉女王</b>坐在她矮小而和善的丈夫身旁。那里的一切都美丽、井然、彬彬有礼，每根柱子后面都藏着<b>拉瑞亚皇家游侠</b>。虚湖没有人说得清拉瑞亚从何而来。",
    "世界向西延伸得更遠了。越過西境的盡頭，西路繼續通往<b>西境深處</b>，一條從沒人劃定的邊界：<b>虛湖</b>王國在 Westwatch 的最後一座哨所（友谷所在的王國終於有了名字）、最初交戰的石原、廢墟、逃兵，以及懸崖間只有一個入口的窪地。龍脊山之後矗立著<b>拉瑞亞</b>，一座環繞宮殿的城牆之城，賢友律法的守護者、光輝的<b>拉拉女王</b>坐在她矮小而和善的丈夫身旁。那裡的一切都美麗、井然、彬彬有禮，每根柱子後面都藏著<b>拉瑞亞皇家遊俠</b>。虛湖沒有人說得清拉瑞亞從何而來。",
    "Thế giới trải dài xa hơn nhiều về phía tây. Qua khỏi tận cùng Westmarch, Con đường phía Tây tiếp tục vào <b>Westmarch Sâu</b>, một biên giới chưa ai vạch: trạm cuối của Vương quốc <b>Hollowmere</b> ở Westwatch (vương quốc của Friendhollow giờ đã có tên), Cánh đồng Đá nơi trận chiến đầu tiên nổ ra, phế tích, lính đào ngũ và một hốc đá trong vách núi chỉ có một lối vào. Sau dãy Drakespine là <b>Raria</b>, một thành phố có tường bao quanh cung điện, nơi Đấng Rạng Ngời <b>Nữ hoàng Rara</b>, Người giữ Luật của Người Bạn Thông Thái, ngồi bên người chồng nhỏ bé hiền lành. Mọi thứ ở đó đều đẹp đẽ, ngăn nắp và lịch sự, và <b>Kiểm lâm Hoàng gia Raria</b> nấp sau mọi cây cột. Không ai ở Hollowmere biết Raria từ đâu đến.",
    "Dunia membentang jauh lebih ke barat. Lewat ujung Westmarch, Jalan Barat berlanjut ke <b>Westmarch Dalam</b>, perbatasan yang tak pernah digambar siapa pun: pos terakhir Kerajaan <b>Hollowmere</b> di Westwatch (kerajaan Friendhollow kini punya nama), Padang Batu tempat pertempuran pertama terjadi, reruntuhan, para desertir, dan sebuah ceruk di tebing dengan satu jalan masuk. Di balik Drakespine berdiri <b>Raria</b>, kota bertembok yang mengelilingi istana, tempat Yang Mulia Bercahaya <b>Ratu Rara</b>, Penjaga Hukum Sahabat Bijak, duduk di samping suaminya yang kecil dan baik hati. Segalanya di sana indah, tertib, dan sopan, dan <b>Penjelajah Kerajaan Raria</b> ada di balik setiap pilar. Tak seorang pun di Hollowmere tahu dari mana Raria berasal.",
    "โลกทอดยาวไปทางตะวันตกไกลกว่าเดิมมาก เลยสุดเขตเวสต์มาร์ช ไป ถนนสายตะวันตกมุ่งต่อเข้าสู่ <b>เวสต์มาร์ชตอนลึก</b> พรมแดนที่ไม่มีใครขีดไว้: ด่านสุดท้ายของอาณาจักร<b>ฮอลโลว์เมียร์</b>ที่ Westwatch (อาณาจักรของเฟรนด์ฮอลโลว์มีชื่อแล้ว) ทุ่งหินที่การสู้รบครั้งแรกเกิดขึ้น ซากปรักหักพัง ทหารหนีทัพ และโพรงในหน้าผาที่มีทางเข้าเพียงทางเดียว หลังเดรกสไปน์ ตั้งตระหง่านด้วย<b>ราเรีย</b> นครกำแพงล้อมรอบพระราชวัง ที่ซึ่งองค์ผู้เปล่งประกาย <b>พระราชินีรารา</b> ผู้พิทักษ์กฎของสหายผู้รอบรู้ ประทับข้างพระสวามีร่างเล็กผู้ใจดี ทุกสิ่งที่นั่นงดงาม เป็นระเบียบ และสุภาพ และมี <b>เรนเจอร์หลวงแห่งราเรีย</b> อยู่หลังเสาทุกต้น ไม่มีใครในฮอลโลว์เมียร์บอกได้ว่าราเรียมาจากไหน",
    "Dünya çok daha batıya uzanıyor. Westmarch'ın sonunu geçince Batı Yolu, kimsenin çizmediği bir sınıra, <b>Deep Westmarch</b>'a devam eder: <b>Hollowmere</b> Krallığı'nın Westwatch'taki son karakolu (Friendhollow'un krallığının artık bir adı var), ilk çarpışmanın olduğu Taş Tarla, harabeler, firariler ve tek bir girişi olan bir uçurum kovuğu. Drakespine'ın ardında bir sarayı çevreleyen surlu şehir <b>Raria</b> yükselir; Wise Friend'in Yasası'nın Koruyucusu, Işıltılı Hazretleri <b>Queen Rara</b>, ufak tefek ve iyi kalpli kocasının yanında oturur. Orada her şey güzel, düzenli ve naziktir, ve her sütunun ardında <b>Raria Royal Rangers</b> vardır. Hollowmere'de kimse Raria'nın nereden geldiğini söyleyemez.",
    "El mundo llega mucho más al oeste. Pasado el final de Westmarch, el Camino del Oeste sigue hasta <b>Westmarch Profundo</b>, una frontera que nadie trazó: el último puesto del Reino de <b>Hollowmere</b> en Westwatch (el reino de Friendhollow ya tiene nombre), el Campo de Piedra donde se libró la primera lucha, ruinas, desertores y una hondonada en los acantilados con una sola entrada. Tras el Drakespine se alza <b>Raria</b>, una ciudad amurallada en torno a un palacio, donde Su Radiancia <b>la reina Rara</b>, Guardiana de la Ley del Amigo Sabio, se sienta junto a su pequeño y bondadoso esposo. Allí todo es hermoso, ordenado y educado, y hay <b>Exploradores Reales de Raria</b> detrás de cada columna. Nadie en Hollowmere sabe decir de dónde salió Raria.",
    "O mundo vai muito mais para o oeste. Passado o fim de Westmarch, a Estrada do Oeste segue para <b>Westmarch Profundo</b>, uma fronteira que ninguém traçou: o último posto do Reino de <b>Hollowmere</b> em Westwatch (o reino de Friendhollow agora tem nome), o Campo de Pedra onde houve a primeira luta, ruínas, desertores e uma reentrância nos penhascos com uma só entrada. Atrás do Drakespine ergue-se <b>Raria</b>, uma cidade murada em volta de um palácio, onde Sua Radiância <b>a Rainha Rara</b>, Guardiã da Lei do Amigo Sábio, senta-se ao lado do marido pequeno e gentil. Tudo ali é belo, ordeiro e educado, e há <b>Patrulheiros Reais de Raria</b> atrás de cada pilar. Ninguém em Hollowmere sabe dizer de onde Raria veio.",
    "Мир простирается намного дальше на запад. За концом Westmarch Западный тракт уходит в <b>Deep Westmarch</b>, границу, которую никто не проводил: последний пост королевства <b>Холлоумир</b> в Westwatch (у королевства Френдхоллоу наконец есть имя), Каменное поле, где случилась первая схватка, руины, дезертиры и расселина в скалах с единственным входом. За Драконьим хребтом (Drakespine) стоит <b>Рария</b>, обнесённый стенами город вокруг дворца, где Её Сияние <b>Queen Rara</b>, Хранительница Закона Wise Friend, сидит рядом со своим маленьким добрым мужем. Там всё красиво, упорядоченно и вежливо, а за каждой колонной стоят <b>Raria Royal Rangers</b>. Никто в Холлоумире не может сказать, откуда взялась Рария.",
    "Світ сягає значно далі на захід. За кінцем Westmarch Західний шлях іде в <b>Deep Westmarch</b>, кордон, якого ніхто не проводив: останній пост королівства <b>Голлоумір</b> у Westwatch (королівство Френдголлоу нарешті має ім'я), Кам'яне поле, де сталася перша сутичка, руїни, дезертири й розколина в скелях з єдиним входом. За Драконячим хребтом (Drakespine) стоїть <b>Рарія</b>, обнесене мурами місто довкола палацу, де Її Сяйво <b>Queen Rara</b>, Хранителька Закону Wise Friend, сидить поруч зі своїм маленьким добрим чоловіком. Там усе гарне, впорядковане й чемне, а за кожною колоною стоять <b>Raria Royal Rangers</b>. Ніхто в Голлоумірі не може сказати, звідки взялася Рарія.",
  ],
  "The <b>Rare Realm Regiment</b> holds the road with camps and a checkpoint; its captain writes writs, and the quests after that make you part of the machine. Once you're received, the Order of Dusk will keep <b>the Wise Friend's Law</b> for you, and your Magic and Faith tabs turn Rarian: edicts, judgements and vigils, the commandments in place of prayer, the rites in place of the old light. In the Free Marches the <b>Free Friends Federation</b> keeps to itself in the <b>FFF Fortress</b>: wizards, knights, rangers and artisans, fourteen devices running in the Great Hall, a cannon, an admiral who is a chicken, and <b>Fellow Free</b>, First Free of the Federation, who is weird, brilliant and dangerous. Between them lies <b>BarkReach</b>, a deep wood of redwoods and ironbarks, and in Ashfall <b>the Burned</b> walk the ash round the Ember Fortress. Every Order now has its own card looks, sealed until you meet its leader, and there are 218 <b>Adventurer Cards</b> to find.": [
    "<b>レアレルム連隊</b>は野営地と検問所で街道を押さえています。隊長は令状を書き、その後のクエストであなたは機構の一部になっていきます。迎え入れられれば、黄昏教団があなたのために<b>賢き友の法</b>を守り、魔法と信仰のタブはラリア式に変わります。勅令、裁き、夜警。祈りの代わりに戒律を、古い光の代わりに儀式を。自由辺境では<b>フリーフレンズ連邦</b>が<b>FFF要塞</b>にこもっています。魔法使い、騎士、レンジャー、職人たち、大広間で動き続ける十四の装置、大砲、ニワトリの提督、そして連邦の第一自由人<b>同志フリー</b>。奇妙で、天才で、危険な人物です。両者のあいだには、セコイアと鉄樹皮の深い森<b>バークリーチ</b>が広がり、アッシュフォールでは<b>焼かれし者たち</b>がエンバー要塞のまわりの灰の上を歩いています。すべての騎士団に専用のカードデザインが加わり、その長に会うまで封印されています。そして見つけるべき<b>冒険者カード</b>は218枚。",
    "<b>레어 렐름 연대</b>는 야영지와 검문소로 길을 지킵니다. 대장은 영장을 쓰고, 그 뒤의 퀘스트들은 당신을 거대한 기계의 일부로 만듭니다. 받아들여지고 나면 황혼 기사단이 당신을 위해 <b>현명한 친구의 법</b>을 지키고, 마법과 신앙 탭은 라리아식으로 바뀝니다. 칙령, 심판, 철야. 기도 대신 계명, 옛 빛 대신 의식. 자유 변경에서는 <b>자유 친구 연방</b>이 <b>FFF 요새</b>에 틀어박혀 지냅니다. 마법사, 기사, 레인저, 장인들, 대회당에서 돌아가는 열네 개의 장치, 대포 한 문, 닭인 제독, 그리고 연방의 제1 자유인 <b>동지 프리</b>. 괴짜이고, 천재이며, 위험한 인물입니다. 그 둘 사이에는 레드우드와 아이언바크의 깊은 숲 <b>바크리치</b>가 있고, 애시폴에서는 <b>불탄 자들</b>이 불씨 요새 주변의 잿더미를 걷습니다. 이제 모든 기사단에 고유한 카드 디자인이 있으며 그 지도자를 만나기 전까지 봉인되어 있고, 찾아낼 <b>모험가 카드</b>는 218장입니다.",
    "<b>稀有王国军团</b>以营地和关卡把守着道路；它的队长签发令状，之后的任务会让你成为这台机器的一部分。一旦被接纳，黄昏骑士团就会为你守护<b>贤友律法</b>，你的魔法与信仰标签页也会变成拉瑞亚式：敕令、裁决与守夜，以戒律代替祈祷，以仪式代替古老的光。在自由边境，<b>自由伙伴联邦</b>闭守在<b>FFF要塞</b>里：巫师、骑士、游侠与工匠，大厅里运转着十四台装置，一门大炮，一位是只鸡的海军上将，还有联邦第一自由人<b>自由同志</b>——古怪、聪明又危险。两者之间是红杉与铁皮树的深林<b>树皮林</b>，而在灰落，<b>焚者</b>在余烬要塞周围的灰烬上游荡。现在每个骑士团都有自己的卡面，在见到其首领之前都处于封印状态；共有 218 张<b>冒险者卡片</b>等你寻找。",
    "<b>稀有王國軍團</b>以營地和關卡把守著道路；它的隊長簽發令狀，之後的任務會讓你成為這台機器的一部分。一旦被接納，黃昏騎士團就會為你守護<b>賢友律法</b>，你的魔法與信仰分頁也會變成拉瑞亞式：敕令、裁決與守夜，以戒律代替祈禱，以儀式代替古老的光。在自由邊境，<b>自由夥伴聯邦</b>閉守在<b>FFF要塞</b>裡：巫師、騎士、遊俠與工匠，大廳裡運轉著十四台裝置，一門大砲，一位是隻雞的海軍上將，還有聯邦第一自由人<b>自由同志</b>——古怪、聰明又危險。兩者之間是紅杉與鐵皮樹的深林<b>樹皮林</b>，而在灰落，<b>焚者</b>在餘燼要塞周圍的灰燼上遊蕩。現在每個騎士團都有自己的卡面，在見到其首領之前都處於封印狀態；共有 218 張<b>冒險者卡片</b>等你尋找。",
    "<b>Trung đoàn Rare Realm</b> giữ con đường bằng doanh trại và trạm kiểm soát; viên đội trưởng viết lệnh, và các nhiệm vụ sau đó biến bạn thành một phần của bộ máy. Một khi được chấp nhận, Dòng Hoàng Hôn sẽ giữ <b>Luật của Người Bạn Thông Thái</b> thay bạn, và các thẻ Phép thuật và Đức tin của bạn chuyển sang kiểu Raria: sắc lệnh, phán quyết và canh thức, điều răn thay cho lời cầu nguyện, nghi lễ thay cho ánh sáng xưa. Ở Miền Biên Tự do, <b>Liên bang Friend Tự do</b> sống khép kín trong <b>Pháo đài FFF</b>: pháp sư, hiệp sĩ, kiểm lâm và thợ thủ công, mười bốn cỗ máy chạy trong Đại sảnh, một khẩu pháo, một đô đốc là con gà, và <b>Đồng chí Free</b>, Người Tự do Thứ nhất của Liên bang, kỳ quặc, xuất chúng và nguy hiểm. Giữa họ là <b>BarkReach</b>, khu rừng sâu của cây gỗ đỏ và cây vỏ sắt, còn ở Ashfall, <b>Những Kẻ Bị Thiêu</b> lang thang trên tro quanh Pháo đài Than Hồng. Giờ đây mỗi Dòng đều có kiểu thẻ riêng, bị niêm phong cho đến khi bạn gặp người đứng đầu, và có 218 <b>Thẻ Nhà thám hiểm</b> chờ bạn tìm.",
    "<b>Resimen Rare Realm</b> menjaga jalan dengan perkemahan dan pos pemeriksaan; kaptennya menulis surat perintah, dan misi-misi sesudahnya menjadikan Anda bagian dari mesin itu. Begitu Anda diterima, Ordo Senja akan menjaga <b>Hukum Sahabat Bijak</b> untuk Anda, dan tab Sihir serta Iman Anda berubah menjadi ala Raria: dekret, penghakiman, dan jaga malam, perintah suci sebagai ganti doa, ritus sebagai ganti cahaya lama. Di Tapal Batas Bebas, <b>Federasi Friend Bebas</b> menyendiri di <b>Benteng FFF</b>: penyihir, kesatria, penjelajah, dan perajin, empat belas perangkat yang berjalan di Aula Besar, sebuah meriam, seorang laksamana yang berupa ayam, dan <b>Kawan Free</b>, Insan Bebas Pertama Federasi, yang aneh, cemerlang, dan berbahaya. Di antara keduanya terbentang <b>BarkReach</b>, hutan lebat pohon redwood dan ironbark, dan di Ashfall <b>Yang Terbakar</b> berjalan di atas abu di sekitar Benteng Bara. Setiap Ordo kini punya tampilan kartunya sendiri, tersegel sampai Anda bertemu pemimpinnya, dan ada 218 <b>Kartu Petualang</b> untuk ditemukan.",
    "<b>กองทหารแรร์เรล์ม</b> ยึดถนนไว้ด้วยค่ายและด่านตรวจ กัปตันของพวกเขาออกหมาย และเควสต์หลังจากนั้นจะทำให้คุณกลายเป็นส่วนหนึ่งของกลไก เมื่อคุณได้รับการยอมรับ ภาคีสนธยาจะรักษา<b>กฎของสหายผู้รอบรู้</b> ไว้ให้คุณ และแท็บเวทมนตร์กับศรัทธาของคุณจะกลายเป็นแบบราเรีย: พระราชกฤษฎีกา การพิพากษา และการเฝ้ายาม บัญญัติแทนคำอธิษฐาน พิธีกรรมแทนแสงสว่างเก่า ในดินแดนชายแดนเสรี <b>สหพันธ์เพื่อนเสรี</b> เก็บตัวอยู่ใน <b>ป้อม FFF</b>: พ่อมด อัศวิน เรนเจอร์ และช่างฝีมือ เครื่องกลสิบสี่เครื่องที่ทำงานอยู่ในห้องโถงใหญ่ ปืนใหญ่หนึ่งกระบอก พลเรือเอกที่เป็นไก่ และ <b>สหายฟรี</b> ผู้เป็นอิสระคนแรกแห่งสหพันธ์ ผู้แปลกประหลาด ปราดเปรื่อง และอันตราย ระหว่างพวกเขาคือ<b>บาร์กรีช</b> ป่าลึกแห่งต้นเรดวูดและต้นไอรอนบาร์ก และในแอชฟอลล์ <b>ผู้ถูกเผา</b>เดินบนเถ้ารอบป้อมถ่านไฟ ทุกภาคีมีหน้าตาการ์ดของตัวเองแล้ว ซึ่งถูกผนึกไว้จนกว่าคุณจะพบผู้นำ และมี<b>การ์ดนักผจญภัย</b> 218 ใบให้ตามหา",
    "<b>Rare Realm Regiment</b> yolu kamplar ve bir kontrol noktasıyla tutar; yüzbaşısı emirname yazar ve sonraki görevler sizi makinenin bir parçası yapar. Kabul edildiğinizde Alacakaranlık Tarikatı sizin için <b>Wise Friend'in Yasası</b>'nı korur, Büyü ve İnanç sekmeleriniz de Raria usulüne döner: fermanlar, hükümler ve nöbetler; dua yerine emirler, eski ışık yerine ayinler. Free Marches'ta <b>Free Friends Federation</b>, <b>FFF Fortress</b>'ta kendi hâlinde yaşar: büyücüler, şövalyeler, korucular ve zanaatkârlar, Büyük Salon'da çalışan on dört düzenek, bir top, tavuk olan bir amiral ve Federasyon'un İlk Özgürü <b>Fellow Free</b>; tuhaf, parlak ve tehlikeli biri. İkisinin arasında sekoyalar ve demir kabuklu ağaçlardan oluşan derin bir orman, <b>BarkReach</b> uzanır; Ashfall'da ise <b>Yanmışlar</b> Ember Fortress'ın çevresindeki külde dolaşır. Artık her Tarikat'ın, liderini görene dek mühürlü kalan kendi kart görünümü var ve bulunacak 218 <b>Maceracı Kartı</b> sizi bekliyor.",
    "El <b>Regimiento del Reino Raro</b> controla el camino con campamentos y un puesto de control; su capitán redacta órdenes, y las misiones que siguen te convierten en parte de la maquinaria. Una vez recibido, la Orden del Ocaso guardará <b>la Ley del Amigo Sabio</b> por ti, y tus pestañas de Magia y Fe se vuelven rarianas: edictos, juicios y vigilias, los mandamientos en lugar de la oración, los ritos en lugar de la vieja luz. En las Marcas Libres, la <b>Federación de Friends Libres</b> vive a su aire en la <b>Fortaleza del FFF</b>: magos, caballeros, exploradores y artesanos, catorce artilugios funcionando en el Gran Salón, un cañón, un almirante que es una gallina y <b>Compañero Libre</b>, Primer Libre de la Federación, que es raro, brillante y peligroso. Entre ambos se extiende <b>BarkReach</b>, un bosque profundo de secuoyas y cortezas de hierro, y en Ashfall <b>Los Quemados</b> recorren la ceniza alrededor de la Fortaleza de la Brasa. Ahora cada Orden tiene su propio diseño de carta, sellado hasta que conozcas a su líder, y hay 218 <b>Cartas de Aventurero</b> por encontrar.",
    "O <b>Regimento do Reino Raro</b> controla a estrada com acampamentos e um posto de controle; seu capitão redige mandados, e as missões seguintes fazem de você parte da engrenagem. Depois de aceito, a Ordem do Crepúsculo guardará <b>a Lei do Amigo Sábio</b> por você, e suas abas de Magia e Fé ficam rarianas: éditos, julgamentos e vigílias, os mandamentos no lugar da oração, os ritos no lugar da velha luz. Nas Marcas Livres, a <b>Federação dos Friends Livres</b> vive na sua, na <b>Fortaleza do FFF</b>: magos, cavaleiros, patrulheiros e artesãos, catorze engenhocas funcionando no Grande Salão, um canhão, um almirante que é uma galinha e <b>Companheiro Livre</b>, Primeiro Livre da Federação, que é esquisito, brilhante e perigoso. Entre eles fica <b>BarkReach</b>, uma floresta profunda de sequoias e cascas-de-ferro, e em Ashfall <b>Os Queimados</b> caminham pelas cinzas ao redor da Fortaleza da Brasa. Agora cada Ordem tem o próprio visual de carta, lacrado até você conhecer seu líder, e há 218 <b>Cartas de Aventureiro</b> para encontrar.",
    "<b>Rare Realm Regiment</b> держит дорогу лагерями и заставой; его капитан выписывает предписания, а следующие задания делают вас частью машины. Когда вас примут, Орден Сумерек будет хранить для вас <b>Закон Wise Friend</b>, а вкладки магии и веры станут рарийскими: эдикты, приговоры и бдения, заповеди вместо молитв, обряды вместо старого света. В Free Marches <b>Free Friends Federation</b> держится особняком в <b>FFF Fortress</b>: волшебники, рыцари, следопыты и ремесленники, четырнадцать механизмов, работающих в Большом зале, пушка, адмирал-курица и <b>Fellow Free</b>, Первый Свободный Федерации, — странный, блестящий и опасный. Между ними лежит <b>Баркрич</b>, глухой лес секвой и железнокоров, а в Эшфолле <b>Сожжённые</b> бродят по пеплу вокруг Ember Fortress. Теперь у каждого ордена свой облик карт, запечатанный, пока вы не встретите его главу, и найти можно 218 <b>карт искателя</b>.",
    "<b>Rare Realm Regiment</b> тримає дорогу таборами й заставою; його капітан виписує приписи, а наступні завдання роблять вас частиною машини. Щойно вас приймуть, Орден Сутінків берегтиме для вас <b>Закон Wise Friend</b>, а вкладки магії та віри стануть рарійськими: едикти, вироки й чування, заповіді замість молитов, обряди замість старого світла. У Free Marches <b>Free Friends Federation</b> тримається осторонь у <b>FFF Fortress</b>: чарівники, лицарі, слідопити й ремісники, чотирнадцять механізмів, що працюють у Великій залі, гармата, адмірал-курка і <b>Fellow Free</b>, Перший Вільний Федерації, — дивакуватий, блискучий і небезпечний. Між ними лежить <b>Баркріч</b>, глибокий ліс секвой і залізнокорів, а в Ешфоллі <b>Спалені</b> блукають попелом довкола Ember Fortress. Тепер кожен орден має власний вигляд карток, запечатаний, доки ви не зустрінете його очільника, і знайти можна 218 <b>карток шукача</b>.",
  ],
  "And Raria is not a sliver behind the Drakespine: the world has grown by a whole <b>second continent</b> to the west. The capital is a great walled city of towers, offices, markets and barracks round the palace; round it lie the Crownlands and their lake town, the Vesperwold's abbey and the Royal Rangers' Hold, the snowbound <b>Silent Peaks</b> and their blindfolded watchers, and the Crown Road east to Lawgate on the eastern march. South of the kingdom the <b>Greyfields</b> hold Fort Ordinance and the Federation's forward camp across a battlefield, and south again <b>BarkReach</b> is a great wood of thousands of trees, with the <b>Heartwood</b> at its oldest end, where the Ironbark Elder walks.": [
    "そしてラリアはドレイクスパインの陰の細長い土地ではありません。世界は西へ、まるごと<b>第二の大陸</b>ぶん広がりました。都は宮殿を囲む塔、役所、市場、兵舎の立ち並ぶ巨大な城塞都市。そのまわりには王領地とその湖畔の町、Vesperwold の修道院と王立レンジャーの砦、雪に閉ざされた<b>沈黙の峰</b>と目隠しをした見張りたち、そして東の辺境ローゲートへと続く王の道があります。王国の南では<b>灰色の野</b>が、戦場を挟んで Fort Ordinance と連邦の前線基地を抱え、さらに南の<b>バークリーチ</b>は何千本もの木が茂る大森林で、そのいちばん古い端には鉄樹皮の長老が歩く<b>ハートウッド</b>があります。",
    "그리고 라리아는 드레이크스파인 뒤의 좁은 땅이 아닙니다. 세계는 서쪽으로 <b>두 번째 대륙</b> 하나만큼 넓어졌습니다. 수도는 궁전을 둘러싼 탑, 관청, 시장, 병영으로 이루어진 거대한 성벽 도시이고, 그 주위에는 왕령지와 호숫가 마을, Vesperwold의 수도원과 왕실 레인저단의 요새, 눈에 갇힌 <b>침묵의 봉우리</b>와 눈을 가린 감시자들, 그리고 동쪽 변경의 로게이트로 이어지는 왕의 길이 있습니다. 왕국 남쪽의 <b>회색 들판</b>에는 전장을 사이에 두고 Fort Ordinance와 연방의 전진 기지가 있고, 더 남쪽의 <b>바크리치</b>는 수천 그루의 나무가 자라는 큰 숲으로, 가장 오래된 끝자락에는 아이언바크 장로가 거니는 <b>하트우드</b>가 있습니다.",
    "而且拉瑞亚并不是龙脊山后面的一条窄地：世界向西扩展出了整整一块<b>第二大陆</b>。都城是一座巨大的城墙之城，塔楼、官署、市场和兵营环绕着宫殿；四周是王领及其湖畔小镇、Vesperwold 的修道院和皇家游侠的要塞、冰雪封锁的<b>寂静峰</b>及其蒙眼的守望者，还有向东通往东部边境律门的王道。王国以南的<b>灰原</b>隔着一片战场，坐落着 Fort Ordinance 和联邦的前沿营地；再往南，<b>树皮林</b>是一片有数千棵树的大森林，最古老的一端是<b>心木林</b>，铁皮树长老在那里行走。",
    "而且拉瑞亞並不是龍脊山後面的一條窄地：世界向西擴展出了整整一塊<b>第二大陸</b>。都城是一座巨大的城牆之城，塔樓、官署、市場和兵營環繞著宮殿；四周是王領及其湖畔小鎮、Vesperwold 的修道院和皇家遊俠的要塞、冰雪封鎖的<b>寂靜峰</b>及其蒙眼的守望者，還有向東通往東部邊境律門的王道。王國以南的<b>灰原</b>隔著一片戰場，坐落著 Fort Ordinance 和聯邦的前沿營地；再往南，<b>樹皮林</b>是一片有數千棵樹的大森林，最古老的一端是<b>心木林</b>，鐵皮樹長老在那裡行走。",
    "Và Raria không phải một dải đất mỏng sau dãy Drakespine: thế giới đã rộng thêm cả một <b>lục địa thứ hai</b> về phía tây. Kinh đô là một thành phố tường bao rộng lớn với tháp, công sở, chợ và doanh trại quanh cung điện; xung quanh là Đất Hoàng gia và thị trấn bên hồ, tu viện Vesperwold và Pháo đài của Kiểm lâm Hoàng gia, <b>Dãy Núi Lặng</b> phủ tuyết cùng những người canh gác bịt mắt, và Con đường Vương miện chạy về phía đông tới Lawgate ở biên cương phía đông. Phía nam vương quốc, <b>Greyfields</b> có Fort Ordinance và doanh trại tiền tuyến của Liên bang hai bên một chiến trường, và xa hơn về phía nam, <b>BarkReach</b> là khu rừng lớn với hàng nghìn cây, với <b>Heartwood</b> ở đầu cổ xưa nhất, nơi Trưởng lão Vỏ sắt bước đi.",
    "Dan Raria bukan sekadar sepotong tanah di balik Drakespine: dunia bertambah luas dengan sebuah <b>benua kedua</b> di barat. Ibu kotanya adalah kota bertembok besar berisi menara, kantor, pasar, dan barak di sekeliling istana; di sekitarnya terbentang Tanah Mahkota dan kota danaunya, biara Vesperwold dan Benteng Penjelajah Kerajaan, <b>Puncak Sunyi</b> yang tertutup salju dengan para penjaga bermata tertutup, dan Jalan Mahkota ke timur menuju Lawgate di perbatasan timur. Di selatan kerajaan, <b>Greyfields</b> menampung Fort Ordinance dan perkemahan depan Federasi di seberang medan perang, dan lebih ke selatan lagi <b>BarkReach</b> adalah hutan besar berisi ribuan pohon, dengan <b>Heartwood</b> di ujungnya yang tertua, tempat Tetua Ironbark berjalan.",
    "และราเรียไม่ใช่แค่ผืนดินแคบ ๆ หลังเดรกสไปน์ โลกขยายออกไปทางตะวันตกเป็น<b>ทวีปที่สอง</b>ทั้งทวีป เมืองหลวงเป็นนครกำแพงขนาดมหึมาที่มีหอคอย สำนักงาน ตลาด และค่ายทหารล้อมรอบพระราชวัง รอบ ๆ คือดินแดนมงกุฎและเมืองริมทะเลสาบ อารามแห่ง Vesperwold และป้อมของเรนเจอร์หลวง <b>ยอดเขาเงียบงัน</b> ที่ถูกหิมะปิดล้อมพร้อมผู้เฝ้ามองที่ปิดตา และถนนมงกุฎที่มุ่งตะวันออกไปยังลอว์เกต ที่ชายแดนตะวันออก ทางใต้ของอาณาจักร <b>ทุ่งสีเทา</b> มี Fort Ordinance และค่ายแนวหน้าของสหพันธ์อยู่คนละฟากสนามรบ และใต้ลงไปอีก <b>บาร์กรีช</b>เป็นป่าใหญ่ที่มีต้นไม้นับพัน โดยมี <b>Heartwood</b> อยู่ที่ปลายสุดที่เก่าแก่ที่สุด ที่ซึ่งผู้อาวุโสไอรอนบาร์กเดินอยู่",
    "Üstelik Raria, Drakespine'ın ardında ince bir şerit değil: dünya batıda koca bir <b>ikinci kıta</b> kadar büyüdü. Başkent, sarayın çevresinde kuleler, daireler, pazarlar ve kışlalardan oluşan büyük, surlu bir şehir; çevresinde Taç Toprakları ve göl kasabası, Vesperwold'un manastırı ve Royal Rangers'ın Kalesi, karla kaplı <b>Silent Peaks</b> ve gözleri bağlı gözcüleri, ve doğu sınırındaki Lawgate'e uzanan Taç Yolu var. Krallığın güneyinde <b>Greyfields</b>, bir savaş alanının iki yanında Fort Ordinance'ı ve Federasyon'un öncü kampını barındırır; daha da güneyde <b>BarkReach</b>, binlerce ağaçlı büyük bir ormandır ve en eski ucunda Demirkabuk Bilge'nin dolaştığı <b>Heartwood</b> bulunur.",
    "Y Raria no es una franja tras el Drakespine: el mundo ha crecido todo un <b>segundo continente</b> hacia el oeste. La capital es una gran ciudad amurallada de torres, oficinas, mercados y cuarteles en torno al palacio; a su alrededor están las Tierras de la Corona y su pueblo del lago, la abadía del Vesperwold y el Bastión de los Exploradores Reales, las nevadas <b>Picos Silenciosos</b> y sus vigías con los ojos vendados, y el Camino de la Corona hacia el este hasta Lawgate, en la marca oriental. Al sur del reino, los <b>Campos Grises</b> albergan Fort Ordinance y el campamento avanzado de la Federación a ambos lados de un campo de batalla, y más al sur aún <b>BarkReach</b> es un gran bosque de miles de árboles, con el <b>Heartwood</b> en su extremo más antiguo, donde camina el Anciano Corteza de Hierro.",
    "E Raria não é uma faixa atrás do Drakespine: o mundo ganhou um <b>segundo continente</b> inteiro a oeste. A capital é uma grande cidade murada de torres, repartições, mercados e quartéis em volta do palácio; ao redor ficam as Terras da Coroa e sua vila do lago, a abadia do Vesperwold e o Bastião dos Patrulheiros Reais, os nevados <b>Picos Silenciosos</b> e seus vigias de olhos vendados, e a Estrada da Coroa para o leste até Lawgate, na marca oriental. Ao sul do reino, os <b>Campos Cinzentos</b> abrigam o Fort Ordinance e o acampamento avançado da Federação, um de cada lado de um campo de batalha, e mais ao sul <b>BarkReach</b> é uma grande floresta de milhares de árvores, com o <b>Heartwood</b> na sua ponta mais antiga, onde anda o Ancião Casca-de-Ferro.",
    "И Рария — не узкая полоска за Драконьим хребтом: мир вырос на целый <b>второй континент</b> к западу. Столица — огромный обнесённый стенами город башен, ведомств, рынков и казарм вокруг дворца; вокруг лежат Коронные земли с их озёрным городком, аббатство Vesperwold и Твердыня Royal Rangers, заснеженные <b>Silent Peaks</b> с их дозорными с завязанными глазами и Коронный тракт на восток, к Lawgate на восточной марке. К югу от королевства в <b>Greyfields</b> по разные стороны поля битвы стоят Fort Ordinance и передовой лагерь Федерации, а ещё южнее <b>Баркрич</b> — огромный лес из тысяч деревьев, и на самом древнем его краю лежит <b>Heartwood</b>, где бродит Старейшина-железнокор.",
    "І Рарія — не вузька смужка за Драконячим хребтом: світ виріс на цілий <b>другий континент</b> на захід. Столиця — величезне обнесене мурами місто веж, установ, ринків і казарм довкола палацу; довкола лежать Коронні землі з їхнім озерним містечком, абатство Vesperwold і Твердиня Royal Rangers, засніжені <b>Silent Peaks</b> з їхніми дозорцями із зав'язаними очима та Коронний шлях на схід, до Lawgate на східній марці. На південь від королівства в <b>Greyfields</b> по різні боки поля битви стоять Fort Ordinance і передовий табір Федерації, а ще південніше <b>Баркріч</b> — величезний ліс із тисяч дерев, і на найдавнішому його краю лежить <b>Heartwood</b>, де ходить Старійшина-залізнокір.",
  ],
  "Before that: the Rare Friends Ring, three new dungeons, and faith weapons in every metal": ["その前は: レアフレンズ・リング、三つの新ダンジョン、そしてあらゆる金属の信仰の武器", "그 전에는: 레어 프렌즈 링, 새 던전 셋, 그리고 모든 금속의 신앙 무기", "在那之前：稀有伙伴擂台、三座新地下城，以及各种金属的信仰武器", "在那之前：稀有夥伴擂台、三座新地下城，以及各種金屬的信仰武器", "Trước đó: Đấu trường Rare Friends, ba ngục tối mới và vũ khí đức tin bằng mọi kim loại", "Sebelumnya: Ring Rare Friends, tiga dungeon baru, dan senjata iman dari setiap logam", "ก่อนหน้านั้น: สังเวียนแรร์เฟรนด์ส, สามดันเจียนใหม่ และอาวุธศรัทธาทุกชนิดโลหะ", "Ondan önce: Rare Friends Ring, üç yeni zindan ve her metalden inanç silahları", "Antes de eso: el Ring de los Rare Friends, tres mazmorras nuevas y armas de fe en todos los metales", "Antes disso: o Ringue dos Rare Friends, três novas masmorras e armas de fé em todos os metais", "До этого: Rare Friends Ring, три новых подземелья и оружие веры из любого металла", "До цього: Rare Friends Ring, три нові підземелля та зброя віри з будь-якого металу"],
  "West of the Deadwood, across the river, stands <b>the Rare Friends Ring</b>: a round building the shape of a Hoverer, built long ago so the best fighters in the land could meet. Its concourse holds every shop a fighter needs; its courtyard is the arena, with the Ringmaker's statue over a fountain that runs red, a garden, a rock field, a little volcano and bones everywhere. Name a match with the Ringmaster (or choose your own foes), pay a quarter of the purse at the gate, and the creatures come for you; the iron arena gates stay barred until the last one falls or you do, and the Ring's magic stands the fallen back up in the lobby. Matches pay coins and <b>bloodmarks</b>, Friend Fights pay <b>laurels</b>, and two shops take nothing else: skull masks, the Bloodmark cape, Pitfighter, Ringsteel and Wildfur armour (fur over iron that fights hardest when you're nearly done), the Champion's cape and the Laurel crown. Stone knights guard the gates; statues of <b>the Seven</b>, the revenant and skeletal knights of the Ring's hardest match, ring the courtyard; and the Ringbreaker warhammer throws what it hits back a step.": [
    "枯れ森の西、川の向こうに<b>レアフレンズ・リング</b>が建っています。国じゅうの最強の戦士たちが相まみえるよう、遠い昔に建てられた Hoverer の形の円形の建物です。回廊には戦士に必要な店がすべてそろい、中庭は闘技場。赤い水が流れる噴水の上には Ring の建造者の像、庭、岩場、小さな火山、そしてそこら中に骨。リングマスターに試合を申し込み (相手は自分で選んでも構いません)、門で賞金の四分の一を払えば、魔物たちが襲いかかってきます。鉄の闘技場の門は、最後の一体か、あなたが倒れるまで閉ざされたまま。倒れた者は Ring の魔法でロビーに立ち上がります。試合ではコインと<b>血の印</b>、フレンド同士の戦いでは<b>月桂樹</b>がもらえ、それしか受け取らない店が二つあります。髑髏の仮面、血の印のマント、Pitfighter、Ringsteel、Wildfur の鎧 (鉄の上に毛皮をまとい、追い詰められるほど強くなる)、王者のマント、そして月桂冠。石の騎士が門を守り、Ring 最難関の試合に現れる亡霊と骸骨の騎士<b>七人衆</b>の像が中庭を囲み、リングブレイカーの戦槌は殴った相手を一歩吹き飛ばします。",
    "데드우드 서쪽, 강 건너편에 <b>레어 프렌즈 링</b>이 서 있습니다. 이 땅 최고의 투사들이 겨룰 수 있도록 오래전에 지어진 Hoverer 모양의 원형 건물입니다. 회랑에는 투사에게 필요한 모든 상점이 있고, 안뜰은 투기장입니다. 붉은 물이 흐르는 분수 위의 Ring 건축가 동상, 정원, 바위밭, 작은 화산, 그리고 사방에 널린 뼈. 링마스터에게 경기를 신청하고(상대를 직접 골라도 됩니다) 입구에서 상금의 4분의 1을 내면 괴물들이 몰려옵니다. 철로 된 투기장 문은 마지막 한 마리가 쓰러지거나 당신이 쓰러질 때까지 잠겨 있고, 쓰러진 자는 Ring의 마법으로 로비에서 다시 일어납니다. 경기는 코인과 <b>핏자국</b>을, 친구 대결은 <b>월계수</b>를 주며, 그것만 받는 상점이 두 곳 있습니다. 해골 가면, 핏자국 망토, Pitfighter, Ringsteel, Wildfur 갑옷(쇠 위에 털을 덧댄 것으로 궁지에 몰릴수록 강하게 싸웁니다), 챔피언의 망토, 그리고 월계관. 돌기사들이 문을 지키고, Ring의 가장 어려운 경기에 나오는 망령과 해골 기사 <b>일곱</b>의 동상이 안뜰을 둘러싸며, 링브레이커 전투 망치는 맞은 상대를 한 걸음 날려 버립니다.",
    "枯木林以西、河的对岸，矗立着<b>稀有伙伴擂台</b>：一座 Hoverer 形状的圆形建筑，很久以前建造，让这片土地上最强的斗士们得以交锋。它的回廊里有斗士所需的每一家店铺；庭院就是竞技场，那里有立在流着红水的喷泉上方的建造者雕像、一座花园、一片乱石地、一座小火山，到处都是骨头。向擂台主报名一场比赛（或自己挑选对手），在门口付四分之一奖金，怪物便会向你扑来；铁铸的竞技场大门会一直紧闭，直到最后一只倒下或你倒下，而 Ring 的魔法会让倒下的人在大厅里重新站起。比赛奖励金币和<b>血印</b>，伙伴之战奖励<b>月桂</b>，有两家店只收这些：骷髅面具、血印披风、Pitfighter、Ringsteel 和 Wildfur 护甲（铁上覆毛皮，越是濒临倒下越能拼命）、冠军披风和月桂冠。石骑士守卫大门；<b>七人</b>的雕像——Ring 最难比赛中的亡魂与骷髅骑士——环绕着庭院；破擂者战锤会把击中的对象击退一步。",
    "枯木林以西、河的對岸，矗立著<b>稀有夥伴擂台</b>：一座 Hoverer 形狀的圓形建築，很久以前建造，讓這片土地上最強的鬥士們得以交鋒。它的迴廊裡有鬥士所需的每一家店鋪；庭院就是競技場，那裡有立在流著紅水的噴泉上方的建造者雕像、一座花園、一片亂石地、一座小火山，到處都是骨頭。向擂台主報名一場比賽（或自己挑選對手），在門口付四分之一獎金，怪物便會向你撲來；鐵鑄的競技場大門會一直緊閉，直到最後一隻倒下或你倒下，而 Ring 的魔法會讓倒下的人在大廳裡重新站起。比賽獎勵金幣和<b>血印</b>，夥伴之戰獎勵<b>月桂</b>，有兩家店只收這些：骷髏面具、血印披風、Pitfighter、Ringsteel 和 Wildfur 護甲（鐵上覆毛皮，越是瀕臨倒下越能拚命）、冠軍披風和月桂冠。石騎士守衛大門；<b>七人</b>的雕像——Ring 最難比賽中的亡魂與骷髏騎士——環繞著庭院；破擂者戰錘會把擊中的對象擊退一步。",
    "Phía tây Deadwood, bên kia sông, là <b>Đấu trường Rare Friends</b>: một tòa nhà tròn hình Hoverer, xây từ lâu để những chiến binh giỏi nhất vùng có thể gặp nhau. Hành lang có mọi cửa hàng một chiến binh cần; sân trong là đấu trường, với tượng Người xây Ring trên đài phun nước chảy đỏ, một khu vườn, một bãi đá, một ngọn núi lửa nhỏ và xương khắp nơi. Đặt một trận với Chủ Đấu trường (hoặc tự chọn đối thủ), trả một phần tư tiền thưởng ở cổng, và quái vật sẽ lao tới; cổng sắt của đấu trường đóng chặt cho đến khi con cuối cùng gục ngã hoặc bạn gục ngã, và phép thuật của Ring dựng người ngã dậy ở sảnh. Các trận đấu trả xu và <b>dấu máu</b>, Trận đấu Friend trả <b>nguyệt quế</b>, và có hai cửa hàng chỉ nhận những thứ đó: mặt nạ đầu lâu, áo choàng Dấu máu, giáp Pitfighter, Ringsteel và Wildfur (lông phủ trên sắt, đánh hăng nhất khi bạn sắp gục), áo choàng Nhà vô địch và Vòng nguyệt quế. Hiệp sĩ đá canh cổng; tượng của <b>Bảy Người</b>, các hiệp sĩ hồn ma và xương của trận khó nhất Ring, bao quanh sân; và búa chiến Phá Đấu Trường đẩy lùi thứ nó đánh trúng một bước.",
    "Di barat Deadwood, di seberang sungai, berdiri <b>Ring Rare Friends</b>: bangunan bundar berbentuk Hoverer, dibangun lama sekali agar para petarung terbaik di negeri ini bisa bertemu. Selasarnya memuat setiap toko yang dibutuhkan petarung; halamannya adalah arena, dengan patung Sang Pembuat Ring di atas air mancur yang mengalirkan merah, sebuah taman, padang batu, gunung api kecil, dan tulang di mana-mana. Pesan pertandingan pada Ringmaster (atau pilih lawan sendiri), bayar seperempat hadiah di gerbang, dan makhluk-makhluk akan datang menyerbu; gerbang besi arena tetap terkunci sampai yang terakhir tumbang atau Anda yang tumbang, dan sihir Ring membangkitkan yang jatuh di lobi. Pertandingan memberi koin dan <b>tanda darah</b>, Pertarungan Friend memberi <b>daun salam</b>, dan dua toko hanya menerima itu: topeng tengkorak, mantel Tanda Darah, zirah Pitfighter, Ringsteel, dan Wildfur (bulu di atas besi yang bertarung paling keras saat Anda hampir habis), mantel Juara, dan Mahkota daun salam. Kesatria batu menjaga gerbang; patung <b>Tujuh</b>, kesatria hantu dan tengkorak dari pertandingan tersulit Ring, mengelilingi halaman; dan palu perang Pemecah Ring mendorong apa pun yang dipukulnya mundur selangkah.",
    "ทางตะวันตกของป่าไม้ตาย ข้ามแม่น้ำไป คือ <b>สังเวียนแรร์เฟรนด์ส</b> อาคารทรงกลมรูป Hoverer ที่สร้างมานานแล้วเพื่อให้นักสู้ที่เก่งที่สุดในแผ่นดินได้พบกัน ทางเดินโถงมีทุกร้านที่นักสู้ต้องการ ลานกลางคือสังเวียน มีรูปปั้นผู้สร้าง Ring เหนือน้ำพุที่ไหลเป็นสีแดง สวน ทุ่งหิน ภูเขาไฟเล็ก ๆ และกระดูกเกลื่อนไปทั่ว แจ้งชื่อแมตช์กับริงมาสเตอร์ (หรือเลือกศัตรูเอง) จ่ายหนึ่งในสี่ของเงินรางวัลที่ประตู แล้วเหล่าสัตว์ร้ายจะบุกมาหาคุณ ประตูเหล็กของสังเวียนจะปิดตายจนกว่าตัวสุดท้ายจะล้มหรือคุณล้มเอง และเวทมนตร์ของ Ring จะปลุกผู้ล้มให้ลุกขึ้นที่ล็อบบี้ แมตช์ให้เหรียญและ<b>รอยเลือด</b> การต่อสู้ระหว่าง Friend ให้<b>ลอเรล</b> และมีสองร้านที่รับแค่สิ่งเหล่านี้: หน้ากากหัวกะโหลก ผ้าคลุมรอยเลือด เกราะ Pitfighter, Ringsteel และ Wildfur (ขนสัตว์บนเหล็กที่สู้หนักที่สุดเมื่อคุณใกล้หมดแรง) ผ้าคลุมแชมเปี้ยน และมงกุฎลอเรล อัศวินหินเฝ้าประตู รูปปั้นของ<b>เจ็ดผู้</b> อัศวินวิญญาณและโครงกระดูกจากแมตช์ที่ยากที่สุดของ Ring ล้อมรอบลานกลาง และค้อนศึกผู้ทลายสังเวียนตีสิ่งที่โดนให้ถอยไปหนึ่งก้าว",
    "Deadwood'un batısında, nehrin karşısında <b>Rare Friends Ring</b> durur: diyarın en iyi dövüşçüleri karşılaşabilsin diye uzun zaman önce yapılmış, Hoverer biçiminde yuvarlak bir yapı. Galerisinde bir dövüşçünün ihtiyaç duyduğu her dükkân var; avlusu arenadır: kırmızı akan bir çeşmenin üstünde Ring Yapıcı'nın heykeli, bir bahçe, bir kayalık, küçük bir yanardağ ve her yerde kemikler. Ringmaster'dan bir maç isteyin (ya da rakiplerinizi kendiniz seçin), kapıda ödülün dörtte birini ödeyin ve yaratıklar üzerinize gelsin; demir arena kapıları sonuncusu düşene ya da siz düşene dek sürgülü kalır ve Ring'in büyüsü düşenleri lobide yeniden ayağa kaldırır. Maçlar altın ve <b>kan izi</b>, Friend Dövüşleri <b>defne</b> kazandırır ve yalnızca bunları kabul eden iki dükkân var: kurukafa maskeleri, Kan İzi pelerini, Pitfighter, Ringsteel ve Wildfur zırhları (demir üstüne kürk; işiniz bitmek üzereyken en sert dövüşür), Şampiyon pelerini ve Defne tacı. Kapıları taş şövalyeler korur; Ring'in en zor maçının hortlak ve iskelet şövalyeleri <b>Yediler</b>'in heykelleri avluyu çevreler; Ring kıran savaş çekici de vurduğunu bir adım geri fırlatır.",
    "Al oeste del Deadwood, al otro lado del río, se alza <b>el Ring de los Rare Friends</b>: un edificio redondo con forma de Hoverer, construido hace mucho para que los mejores luchadores del país pudieran enfrentarse. Su explanada tiene todas las tiendas que necesita un luchador; su patio es la arena, con la estatua del Constructor del Ring sobre una fuente que mana rojo, un jardín, un pedregal, un pequeño volcán y huesos por todas partes. Pide un combate al Maestro del Ring (o elige tus propios rivales), paga un cuarto de la bolsa en la puerta y las criaturas irán a por ti; las puertas de hierro de la arena siguen cerradas hasta que cae la última o caes tú, y la magia del Ring levanta a los caídos en el vestíbulo. Los combates dan monedas y <b>marcas de sangre</b>, los Duelos de Friends dan <b>laureles</b>, y dos tiendas no aceptan otra cosa: máscaras de calavera, la capa de la Marca de Sangre, las armaduras Pitfighter, Ringsteel y Wildfur (piel sobre hierro que pelea con más fuerza cuanto más cerca estás del final), la capa de Campeón y la Corona de laurel. Caballeros de piedra guardan las puertas; estatuas de <b>los Siete</b>, los caballeros espectrales y esqueléticos del combate más duro del Ring, rodean el patio; y el martillo de guerra Rompering hace retroceder un paso a lo que golpea.",
    "A oeste de Deadwood, do outro lado do rio, fica <b>o Ringue dos Rare Friends</b>: um prédio redondo no formato de um Hoverer, construído há muito tempo para que os melhores lutadores da terra pudessem se enfrentar. Seu saguão tem todas as lojas de que um lutador precisa; o pátio é a arena, com a estátua do Construtor do Ring sobre uma fonte que corre vermelha, um jardim, um campo de pedras, um pequeno vulcão e ossos por toda parte. Peça uma luta ao Mestre do Ring (ou escolha seus próprios inimigos), pague um quarto do prêmio no portão, e as criaturas virão atrás de você; os portões de ferro da arena ficam trancados até a última cair ou você cair, e a magia do Ring põe os caídos de pé de novo no saguão. As lutas pagam moedas e <b>marcas de sangue</b>, as Lutas de Friends pagam <b>louros</b>, e duas lojas não aceitam mais nada: máscaras de caveira, a capa da Marca de Sangue, as armaduras Pitfighter, Ringsteel e Wildfur (pele sobre ferro que luta mais forte quando você está quase no fim), a capa de Campeão e a Coroa de louros. Cavaleiros de pedra guardam os portões; estátuas dos <b>Sete</b>, os cavaleiros espectrais e esqueléticos da luta mais difícil do Ring, cercam o pátio; e o martelo de guerra Quebra-ringue empurra um passo para trás o que acerta.",
    "К западу от Deadwood, за рекой, стоит <b>Rare Friends Ring</b>: круглое здание в форме Hoverer, построенное давным-давно, чтобы лучшие бойцы страны могли сойтись друг с другом. В его галерее есть все лавки, нужные бойцу; двор — это арена: статуя Создателя Ринга над фонтаном, из которого течёт красное, сад, каменистое поле, маленький вулкан и кости повсюду. Назначьте бой у распорядителя (или выберите противников сами), заплатите у ворот четверть призовых, и твари придут за вами; железные ворота арены остаются запертыми, пока не падёт последняя тварь или вы сами, а магия Ринга поднимает павших на ноги в вестибюле. Бои приносят монеты и <b>кровавые метки</b>, бои Friend — <b>лавры</b>, и две лавки принимают только их: черепа-маски, плащ кровавой метки, броня Pitfighter, Ringsteel и Wildfur (мех поверх железа, который бьётся сильнее всего, когда вы почти на исходе), плащ чемпиона и лавровый венец. Ворота стерегут каменные рыцари; двор окружают статуи <b>Семерых</b> — призрачных и скелетных рыцарей самого тяжёлого боя Ринга; а боевой молот Крушитель Ринга отбрасывает того, кого бьёт, на шаг назад.",
    "На захід від Deadwood, за річкою, стоїть <b>Rare Friends Ring</b>: кругла будівля у формі Hoverer, збудована давним-давно, щоб найкращі бійці краю могли зійтися між собою. У її галереї є всі крамниці, потрібні бійцеві; двір — це арена: статуя Творця Рингу над фонтаном, з якого тече червоне, сад, кам'янисте поле, маленький вулкан і кістки всюди. Замовте бій у розпорядника (або виберіть суперників самі), заплатіть біля воріт чверть призових, і потвори прийдуть по вас; залізні ворота арени лишаються замкненими, доки не впаде остання потвора або ви самі, а магія Рингу підводить полеглих на ноги у вестибюлі. Бої приносять монети й <b>криваві мітки</b>, бої Friend — <b>лаври</b>, і дві крамниці приймають тільки їх: маски-черепи, плащ кривавої мітки, броня Pitfighter, Ringsteel і Wildfur (хутро поверх заліза, що б'ється найзавзятіше, коли ви майже знесилені), плащ чемпіона й лавровий вінець. Ворота стережуть кам'яні лицарі; двір оточують статуї <b>Сімох</b> — примарних і скелетних лицарів найважчого бою Рингу; а бойовий молот Трощитель Рингу відкидає того, кого б'є, на крок назад.",
  ],
  "Below the lake, the library and the standing stones: <b>the Deepglass Caverns</b>, <b>the Drowned Archive</b> and <b>the Howling Vault</b>, each with a boss behind a door that takes a key, archers that shoot from across a room, wraiths that drain faith, a keeper who mends himself, and coffers in every dungeon with loot that belongs there and a slim chance at something rare. Three quests, six Slayer tasks, and a statue at every dungeon's mouth of what waits below. And for those who fight by faith: a mace and a flail in every metal, the aegis and the round shield, and the Faith spellbook.": [
    "湖と図書館と立石の下に: <b>ディープグラス洞窟</b>、<b>Drowned Archive</b>、<b>遠吠えの霊廟</b>。どれも鍵のいる扉の奥にボスがいて、部屋の向こうから射ってくる弓兵、信仰を吸い取る亡霊、自分を修復する番人、そしてすべてのダンジョンに、その場所にふさわしい戦利品とわずかなレアのチャンスが入った宝箱があります。クエスト三つ、討伐任務六つ、そして各ダンジョンの入り口には下で待つものの像。信仰で戦う者には、あらゆる金属のメイスとフレイル、イージスと丸盾、そして信仰の呪文書。",
    "호수와 도서관과 선돌 아래에: <b>심연유리 동굴</b>, <b>Drowned Archive</b>, <b>울부짖는 납골당</b>. 모두 열쇠가 필요한 문 너머에 보스가 있고, 방 건너편에서 쏘는 궁수, 신앙을 빨아들이는 망령, 스스로를 고치는 관리인, 그리고 모든 던전마다 그곳에 어울리는 전리품과 희귀품을 얻을 작은 확률이 든 금고가 있습니다. 퀘스트 셋, 토벌 임무 여섯, 그리고 던전 입구마다 아래에서 기다리는 것의 동상. 신앙으로 싸우는 이들을 위해서는 모든 금속의 철퇴와 도리깨, 아이기스와 원형 방패, 그리고 신앙 주문서.",
    "在湖泊、图书馆和立石之下：<b>深玻洞窟</b>、<b>Drowned Archive</b>和<b>嚎叫地窖</b>，每一座都有一位藏在需要钥匙的门后的首领、能隔着房间射击的弓箭手、吸取信仰的幽魂、会自我修复的看守者，每座地下城里还有宝箱，装着属于那里的战利品和获得稀有物品的一丝机会。三个任务、六个猎杀任务，每座地下城入口都有一尊雕像，展示下面等着你的东西。而对于以信仰战斗的人：各种金属的钉锤和连枷、圣盾和圆盾，以及信仰法术书。",
    "在湖泊、圖書館和立石之下：<b>深玻洞窟</b>、<b>Drowned Archive</b>和<b>嚎叫地窖</b>，每一座都有一位藏在需要鑰匙的門後的首領、能隔著房間射擊的弓箭手、吸取信仰的幽魂、會自我修復的看守者，每座地下城裡還有寶箱，裝著屬於那裡的戰利品和獲得稀有物品的一絲機會。三個任務、六個獵殺任務，每座地下城入口都有一尊雕像，展示下面等著你的東西。而對於以信仰戰鬥的人：各種金屬的釘錘和連枷、聖盾和圓盾，以及信仰法術書。",
    "Bên dưới hồ, thư viện và những tảng đá dựng: <b>Hang Kính Sâu</b>, <b>Drowned Archive</b> và <b>Hầm Gào Thét</b>, mỗi nơi có một con trùm sau cánh cửa cần chìa khóa, cung thủ bắn từ bên kia phòng, bóng ma hút đức tin, một người giữ cửa tự hồi phục, và rương báu trong mọi ngục tối với chiến lợi phẩm hợp với nơi đó cùng một cơ hội mong manh có được đồ hiếm. Ba nhiệm vụ, sáu nhiệm vụ Diệt quái, và ở miệng mỗi ngục tối là bức tượng của thứ đang chờ bên dưới. Còn cho những ai chiến đấu bằng đức tin: chùy và chùy xích bằng mọi kim loại, khiên aegis và khiên tròn, và sách phép Đức tin.",
    "Di bawah danau, perpustakaan, dan batu tegak: <b>Gua Kaca Dalam</b>, <b>Drowned Archive</b>, dan <b>Ruang Bawah Tanah Melolong</b>, masing-masing dengan bos di balik pintu yang butuh kunci, pemanah yang menembak dari seberang ruangan, hantu yang menguras iman, penjaga yang menyembuhkan dirinya sendiri, dan peti harta di setiap dungeon berisi jarahan yang khas tempat itu dan sedikit peluang mendapat sesuatu yang langka. Tiga misi, enam tugas Pembasmi, dan patung di mulut setiap dungeon tentang apa yang menunggu di bawah. Dan bagi mereka yang bertarung dengan iman: gada dan cambuk berantai dari setiap logam, aegis dan perisai bundar, serta buku mantra Iman.",
    "ใต้ทะเลสาบ ห้องสมุด และหินตั้ง: <b>ถ้ำแก้วลึก</b>, <b>Drowned Archive</b> และ <b>ห้องใต้ดินหอนครวญ</b> แต่ละแห่งมีบอสอยู่หลังประตูที่ต้องใช้กุญแจ นักธนูที่ยิงมาจากอีกฟากห้อง ภูตที่ดูดศรัทธา ผู้เฝ้าที่ซ่อมแซมตัวเองได้ และหีบสมบัติในทุกดันเจียนที่มีของรางวัลเข้ากับสถานที่และโอกาสเล็ก ๆ ที่จะได้ของหายาก สามเควสต์ หกภารกิจล่าอสูร และรูปปั้นที่ปากทางทุกดันเจียนของสิ่งที่รออยู่เบื้องล่าง และสำหรับผู้ที่สู้ด้วยศรัทธา: กระบองและกระบองโซ่ทุกชนิดโลหะ โล่อีจิสและโล่กลม และตำราเวทศรัทธา",
    "Gölün, kütüphanenin ve dikili taşların altında: <b>Deepglass Caverns</b>, <b>Drowned Archive</b> ve <b>Howling Vault</b>; her birinde anahtar isteyen bir kapının ardında bir patron, odanın öbür ucundan ok atan okçular, inancı emen hayaletler, kendini onaran bir bekçi ve her zindanda oraya ait ganimetle nadir bir şey için küçük bir şans barındıran sandıklar var. Üç görev, altı Avcı görevi ve her zindanın ağzında aşağıda bekleyenin heykeli. İnançla savaşanlar içinse: her metalden topuz ve döven, aegis ve yuvarlak kalkan, ve İnanç büyü kitabı.",
    "Bajo el lago, la biblioteca y los menhires: <b>las Cavernas de Vidrio Hondo</b>, <b>el Drowned Archive</b> y <b>la Cámara Aullante</b>, cada una con un jefe tras una puerta que pide llave, arqueros que disparan desde el otro lado de la sala, espectros que drenan la fe, un guardián que se repara solo y cofres en cada mazmorra con botín propio del lugar y una pequeña posibilidad de algo raro. Tres misiones, seis encargos de Cazador y, a la entrada de cada mazmorra, una estatua de lo que espera abajo. Y para quienes luchan con fe: una maza y un mangual en cada metal, la égida y el escudo redondo, y el libro de hechizos de la Fe.",
    "Debaixo do lago, da biblioteca e das pedras erguidas: <b>as Cavernas do Vidro Fundo</b>, <b>o Drowned Archive</b> e <b>a Câmara Uivante</b>, cada uma com um chefe atrás de uma porta que exige chave, arqueiros que atiram do outro lado da sala, espectros que drenam a fé, um guardião que se conserta sozinho e baús em cada masmorra com saques típicos do lugar e uma pequena chance de algo raro. Três missões, seis tarefas de Caçador e, na entrada de cada masmorra, uma estátua do que espera lá embaixo. E para quem luta pela fé: uma maça e um mangual em cada metal, a égide e o escudo redondo, e o grimório da Fé.",
    "Под озером, библиотекой и стоячими камнями: <b>Deepglass Caverns</b>, <b>Drowned Archive</b> и <b>Howling Vault</b>, в каждом босс за дверью, которой нужен ключ, лучники, стреляющие через всю комнату, призраки, высасывающие веру, хранитель, который сам себя чинит, и сундуки в каждом подземелье с добычей, подходящей этому месту, и крошечным шансом на редкость. Три задания, шесть заданий на истребление и у входа в каждое подземелье статуя того, что ждёт внизу. А тем, кто сражается верой: булава и цеп из каждого металла, эгида и круглый щит, и книга заклинаний веры.",
    "Під озером, бібліотекою та стоячими каменями: <b>Deepglass Caverns</b>, <b>Drowned Archive</b> і <b>Howling Vault</b>, у кожному бос за дверима, яким потрібен ключ, лучники, що стріляють через усю кімнату, примари, що висмоктують віру, сторож, який сам себе лагодить, і скрині в кожному підземеллі зі здобиччю, властивою цьому місцю, і крихітним шансом на рідкість. Три завдання, шість завдань на винищення й біля входу в кожне підземелля статуя того, що чекає внизу. А тим, хто б'ється вірою: булава й ціп із кожного металу, егіда й круглий щит, і книга заклять віри.",
  ],
  "Before that: the Wider World, a continent around the Realm you know": ["その前は: Wider World、おなじみのレルムを囲む大陸", "그 전에는: Wider World, 당신이 아는 렐름을 둘러싼 대륙", "在那之前：Wider World，环绕你所熟知的王国的大陆", "在那之前：Wider World，環繞你所熟知的王國的大陸", "Trước đó: Wider World, một lục địa bao quanh Vương quốc bạn biết", "Sebelumnya: Wider World, benua di sekeliling Realm yang Anda kenal", "ก่อนหน้านั้น: Wider World ทวีปที่ล้อมรอบอาณาจักรที่คุณรู้จัก", "Ondan önce: Wider World, bildiğiniz Diyar'ı çevreleyen bir kıta", "Antes de eso: el Wider World, un continente alrededor del Reino que conoces", "Antes disso: o Wider World, um continente ao redor do Reino que você conhece", "До этого: Wider World, континент вокруг знакомого вам Realm", "До цього: Wider World, континент довкола знайомого вам Realm"],
  "The mainland is now the heart of a world four times its size, itself untouched: <b>the Deadwood</b> and Gravesend to the north, <b>Westmarch and the Drakespine</b> to the west with <b>Ashfall</b>, the dragons' country, at the peninsula's end, <b>Southshore</b>, Hollyhock and Dyemoor to the south, <b>Ironreach</b>, Cragmaw, The Wilds and Quillhaven to the east, the Pale Isles at sea. Seven villages in their own clothes with their own quests, four hidden underground dungeons, twenty new tracks. Two new skills: <b>Apothecary</b> (herbs by ecosystem, potions, poisons that matter, antidotes and nine Friend mixtures) and <b>Presence</b> (a character profile: name your Friend, found a fellowship, earn titles and reputation). Before that, in the same month: Wayfaring, the Warden's creatures, the Heartguard and Dawnhold Keep. <b>Agility is now Wayfaring</b>, with three courses, slips, Wayfarer's marks and Coach Skip's outfit; five new <b>Slayer-only creatures</b> each drop an armour set with its own effect (thorns, faith, stealth, fire-proofing, sigil-saving); <b>heavy weapons</b> take Strength and swing harder with it; the <b>Heartguard</b> is red-and-white armour earned a piece every ten Hitpoints levels; <b>Dawnhold</b> has a keep with corner towers and a taller chapel; every altar has a statue of the bearded <b>Old Friend</b>; the quest journal is grouped and coloured, bones offer themselves until you run out, and the Dawn Vigil's <b>ossuary bag</b> holds sixty of them.": [
    "本土は、それ自体はそのままに、四倍の広さの世界の中心になりました。北に<b>枯れ森</b>とグレイヴセンド、西に<b>ウェストマーチとドレイクスパイン</b>、半島の先には竜の国<b>アッシュフォール</b>、南に<b>サウスショア</b>、ホリホック、ダイムーア、東に<b>アイアンリーチ</b>、クラグモー、荒野、クイルヘイヴン、そして海には青白諸島。それぞれの服装とクエストを持つ七つの村、隠された四つの地下ダンジョン、新曲二十。新スキルは二つ: <b>薬学</b> (生態系ごとの薬草、ポーション、効き目のある毒、解毒剤、九種のフレンド用調合薬) と<b>名声</b> (キャラクターのプロフィール: フレンドに名前をつけ、フェローシップを結成し、称号と評判を得る)。その前の同じ月には、旅路、番人の魔物、心臓の守り手、ドーンホールドの天守。<b>敏捷は旅路になりました</b>。コース三つ、すべりやすい足場、旅人の印、コーチ・スキップの衣装つき。<b>討伐専用の魔物</b>五種は、それぞれ独自の効果を持つ防具一式を落とします (とげ、信仰、隠密、耐火、シジル節約)。<b>重武器</b>は筋力を必要とし、筋力が高いほど強く振れます。<b>心臓の守り手</b>はヒットポイントのレベル10ごとに一つずつ手に入る赤と白の鎧。<b>ドーンホールド</b>には角塔のある天守とより高い礼拝堂ができました。すべての祭壇にひげの<b>古き友</b>の像。クエスト日誌はグループ分けされて色がつき、骨は尽きるまで続けて捧げられ、夜明けの寝ずの番の<b>納骨袋</b>には骨が六十本入ります。",
    "본토는 그 자체로는 그대로인 채, 네 배 크기의 세계의 중심이 되었습니다. 북쪽에 <b>데드우드</b>와 그레이브센드, 서쪽에 <b>웨스트마치와 드레이크스파인</b>, 반도 끝에는 용의 땅 <b>애시폴</b>, 남쪽에 <b>사우스쇼어</b>, 할리혹, 다이무어, 동쪽에 <b>아이언리치</b>, 크래그모, 황야, 퀼헤이븐, 그리고 바다에는 창백한 섬들. 저마다의 옷차림과 퀘스트를 가진 일곱 마을, 숨겨진 지하 던전 넷, 새 곡 스무 곡. 새 스킬 둘: <b>약학</b>(생태계별 약초, 물약, 제대로 듣는 독, 해독제, 아홉 가지 친구용 혼합물)과 <b>명성</b>(캐릭터 프로필: 친구에게 이름을 붙이고, 펠로십을 세우고, 칭호와 평판을 얻습니다). 그 전, 같은 달에는: 여행, 감시자의 괴물들, 심장 수호자, 돈홀드 성채. <b>민첩은 이제 여행입니다</b>. 코스 셋, 미끄러지는 발판, 여행자의 표식, 스킵 코치의 의상이 있습니다. 새로운 <b>토벌 전용 괴물</b> 다섯은 저마다 고유 효과가 있는 방어구 세트를 떨어뜨립니다(가시, 신앙, 은신, 내화, 인장 절약). <b>중무기</b>는 힘이 필요하고 힘이 높을수록 더 세게 휘두릅니다. <b>심장 수호자</b>는 체력 10레벨마다 한 부위씩 얻는 빨강과 하양의 갑옷입니다. <b>돈홀드</b>에는 모서리 탑이 있는 성채와 더 높은 예배당이 생겼고, 모든 제단에는 수염 난 <b>옛 친구</b>의 동상이 있습니다. 퀘스트 일지는 묶이고 색이 입혀졌으며, 뼈는 다 떨어질 때까지 계속 바쳐지고, 새벽의 철야의 <b>유골 자루</b>에는 뼈가 예순 개 들어갑니다.",
    "本土本身未被改动，如今成了一个四倍大世界的中心：北方是<b>枯木林</b>和墓终，西方是<b>西境与龙脊山</b>，半岛尽头是龙之国度<b>灰落</b>，南方是<b>南岸</b>、蜀葵村和染原，东方是<b>铁境</b>、崖口、荒野和羽港，海上则是苍白群岛。七个村庄各有服饰与任务，四座隐藏的地下城，二十首新曲。两项新技能：<b>药剂</b>（按生态采集草药、药水、真正有效的毒药、解药和九种伙伴专属调剂）和<b>声望</b>（角色档案：为你的伙伴取名、创立同伴会、赢得称号与声誉）。在那之前的同一个月：行旅、守卫的怪物、心之卫士和晨堡主堡。<b>敏捷现在改为行旅</b>，有三条赛道、滑倒、旅者印记和斯基普教练的服装；五种新的<b>猎杀专属怪物</b>各掉落一套带有独特效果的护甲（荆棘、信仰、潜行、防火、节省印记）；<b>重型武器</b>需要力量，力量越高挥得越狠；<b>心之卫士</b>是红白相间的护甲，生命值每升十级获得一件；<b>晨堡</b>有了带角楼的主堡和更高的礼拜堂；每座祭坛都有大胡子<b>故友</b>的雕像；任务日志已分组上色，骨头会一直献祭到用完，黎明守夜的<b>骨灰袋</b>能装六十根骨头。",
    "本土本身未被改動，如今成了一個四倍大世界的中心：北方是<b>枯木林</b>和墓終，西方是<b>西境與龍脊山</b>，半島盡頭是龍之國度<b>灰落</b>，南方是<b>南岸</b>、蜀葵村和染原，東方是<b>鐵境</b>、崖口、荒野和羽港，海上則是蒼白群島。七個村莊各有服飾與任務，四座隱藏的地下城，二十首新曲。兩項新技能：<b>藥劑</b>（按生態採集草藥、藥水、真正有效的毒藥、解藥和九種夥伴專屬調劑）和<b>聲望</b>（角色檔案：為你的夥伴取名、創立同伴會、贏得稱號與聲譽）。在那之前的同一個月：行旅、守衛的怪物、心之衛士和晨堡主堡。<b>敏捷現在改為行旅</b>，有三條賽道、滑倒、旅者印記和斯基普教練的服裝；五種新的<b>獵殺專屬怪物</b>各掉落一套帶有獨特效果的護甲（荊棘、信仰、潛行、防火、節省印記）；<b>重型武器</b>需要力量，力量越高揮得越狠；<b>心之衛士</b>是紅白相間的護甲，生命值每升十級獲得一件；<b>晨堡</b>有了帶角樓的主堡和更高的禮拜堂；每座祭壇都有大鬍子<b>故友</b>的雕像；任務日誌已分組上色，骨頭會一直獻祭到用完，黎明守夜的<b>骨灰袋</b>能裝六十根骨頭。",
    "Đất liền giờ là trung tâm của một thế giới lớn gấp bốn lần, bản thân nó vẫn nguyên vẹn: <b>Deadwood</b> và Gravesend ở phía bắc, <b>Westmarch và Drakespine</b> ở phía tây với <b>Ashfall</b>, xứ sở của rồng, ở mũi bán đảo, <b>Southshore</b>, Hollyhock và Dyemoor ở phía nam, <b>Ironreach</b>, Cragmaw, Vùng Hoang dã và Quillhaven ở phía đông, Quần đảo Nhợt nhạt ngoài biển. Bảy ngôi làng với trang phục và nhiệm vụ riêng, bốn ngục tối ngầm ẩn giấu, hai mươi bản nhạc mới. Hai kỹ năng mới: <b>Bào chế</b> (thảo dược theo hệ sinh thái, thuốc, chất độc thật sự có tác dụng, thuốc giải và chín hỗn hợp cho Friend) và <b>Danh tiếng</b> (hồ sơ nhân vật: đặt tên cho Friend, lập hội, giành danh hiệu và uy tín). Trước đó, cùng tháng: Lữ hành, quái vật của Người gác, Hộ vệ Trái tim và tòa thành Dawnhold. <b>Nhanh nhẹn giờ là Lữ hành</b>, với ba đường đua, cú trượt chân, dấu Lữ khách và bộ đồ của Huấn luyện viên Skip; năm <b>quái vật chỉ dành cho Diệt quái</b> mới, mỗi con rơi một bộ giáp có hiệu ứng riêng (gai, đức tin, ẩn thân, chống lửa, tiết kiệm ấn); <b>vũ khí nặng</b> cần Sức mạnh và vung mạnh hơn nhờ nó; <b>Hộ vệ Trái tim</b> là bộ giáp đỏ trắng, nhận một món sau mỗi mười cấp Máu; <b>Dawnhold</b> có tòa thành với tháp góc và nhà nguyện cao hơn; mọi bàn thờ đều có tượng <b>Người Bạn Cũ</b> râu rậm; nhật ký nhiệm vụ được nhóm lại và tô màu, xương tự dâng liên tục cho đến khi hết, và <b>túi hài cốt</b> của Canh thức Bình minh chứa được sáu mươi khúc.",
    "Daratan utama kini menjadi jantung dunia yang empat kali lebih besar, dirinya sendiri tak tersentuh: <b>Deadwood</b> dan Gravesend di utara, <b>Westmarch dan Drakespine</b> di barat dengan <b>Ashfall</b>, negeri para naga, di ujung semenanjung, <b>Southshore</b>, Hollyhock, dan Dyemoor di selatan, <b>Ironreach</b>, Cragmaw, The Wilds, dan Quillhaven di timur, Kepulauan Pucat di laut. Tujuh desa dengan pakaian dan misinya sendiri, empat dungeon bawah tanah tersembunyi, dua puluh lagu baru. Dua keahlian baru: <b>Peracik obat</b> (herba menurut ekosistem, ramuan, racun yang berpengaruh, penawar, dan sembilan racikan Friend) dan <b>Kehadiran</b> (profil karakter: beri nama Friend Anda, dirikan persekutuan, raih gelar dan reputasi). Sebelum itu, di bulan yang sama: Pengembaraan, makhluk sang Penjaga, Pengawal Jantung, dan Benteng Dawnhold. <b>Kelincahan kini menjadi Pengembaraan</b>, dengan tiga lintasan, tergelincir, tanda Pengembara, dan pakaian Pelatih Skip; lima <b>makhluk khusus Pembasmi</b> baru masing-masing menjatuhkan satu set zirah dengan efeknya sendiri (duri, iman, siluman, tahan api, hemat sigil); <b>senjata berat</b> butuh Kekuatan dan diayun lebih keras karenanya; <b>Pengawal Jantung</b> adalah zirah merah-putih yang didapat sepotong setiap sepuluh level Nyawa; <b>Dawnhold</b> punya benteng dengan menara sudut dan kapel yang lebih tinggi; setiap altar punya patung <b>Sahabat Lama</b> berjanggut; jurnal misi dikelompokkan dan diwarnai, tulang terus dipersembahkan sampai habis, dan <b>kantong osuarium</b> Jaga Fajar menampung enam puluh tulang.",
    "แผ่นดินใหญ่กลายเป็นหัวใจของโลกที่ใหญ่กว่าเดิมสี่เท่า โดยตัวมันเองไม่ถูกแตะต้อง: <b>ป่าไม้ตาย</b> และเกรฟเซนด์ทางเหนือ <b>เวสต์มาร์ช และเดรกสไปน์</b> ทางตะวันตก พร้อม<b>แอชฟอลล์</b> ดินแดนแห่งมังกร ที่ปลายคาบสมุทร <b>เซาท์ชอร์</b> ฮอลลีฮ็อก และไดมัวร์ทางใต้ <b>ไอรอนรีช</b> แครกมอว์ป่าเถื่อน และควิลเฮเวนทางตะวันออก และหมู่เกาะซีด กลางทะเล เจ็ดหมู่บ้านที่มีเครื่องแต่งกายและเควสต์ของตัวเอง สี่ดันเจียนใต้ดินที่ซ่อนอยู่ และเพลงใหม่ยี่สิบเพลง สองทักษะใหม่: <b>ปรุงยา</b> (สมุนไพรตามระบบนิเวศ ยา พิษที่ได้ผลจริง ยาถอนพิษ และส่วนผสมสำหรับ Friend เก้าชนิด) และ<b>ชื่อเสียง</b> (โปรไฟล์ตัวละคร: ตั้งชื่อ Friend ก่อตั้งกลุ่มสหาย รับฉายาและชื่อเสียง) ก่อนหน้านั้นในเดือนเดียวกัน: การเดินทาง สัตว์ร้ายของผู้คุม ผู้พิทักษ์หัวใจ และหอคอยดอว์นโฮลด์ <b>ความคล่องแคล่วตอนนี้คือการเดินทาง</b> มีสามสนาม การลื่นล้ม ตราผู้เดินทาง และชุดของโค้ชสคิป <b>สัตว์ร้ายเฉพาะล่าอสูร</b>ใหม่ห้าชนิด แต่ละตัวดรอปชุดเกราะที่มีผลพิเศษของตัวเอง (หนาม ศรัทธา ลอบเร้น กันไฟ ประหยัดผนึก) <b>อาวุธหนัก</b>ต้องใช้พละกำลังและฟาดแรงขึ้นตามนั้น <b>ผู้พิทักษ์หัวใจ</b>เป็นเกราะสีแดงขาวที่ได้หนึ่งชิ้นทุกสิบเลเวลพลังชีวิต <b>ดอว์นโฮลด์</b>มีหอคอยพร้อมป้อมมุมและโบสถ์ที่สูงขึ้น ทุกแท่นบูชามีรูปปั้น <b>สหายเก่า</b> ผู้มีเครา สมุดเควสต์ถูกจัดกลุ่มและใส่สี กระดูกถวายต่อเนื่องจนกว่าจะหมด และ<b>ถุงเก็บกระดูก</b>ของการเฝ้ารุ่งอรุณใส่ได้หกสิบชิ้น",
    "Anakara artık kendisi el değmeden, dört kat büyük bir dünyanın kalbi: kuzeyde <b>Deadwood</b> ve Gravesend, batıda <b>Westmarch ve Drakespine</b>, yarımadanın ucunda ejderhaların ülkesi <b>Ashfall</b>, güneyde <b>Southshore</b>, Hollyhock ve Dyemoor, doğuda <b>Ironreach</b>, Cragmaw, The Wilds ve Quillhaven, denizde Pale Isles. Kendi kıyafetleri ve görevleriyle yedi köy, gizli dört yeraltı zindanı, yirmi yeni müzik. İki yeni yetenek: <b>Eczacılık</b> (ekosisteme göre otlar, iksirler, gerçekten işe yarayan zehirler, panzehirler ve dokuz Friend karışımı) ve <b>Şöhret</b> (bir karakter profili: Friend'inize ad verin, bir kardeşlik kurun, unvan ve itibar kazanın). Ondan önce, aynı ay: Yolculuk, Bekçi'nin yaratıkları, Kalp Muhafızı ve Dawnhold Kalesi. <b>Çeviklik artık Yolculuk</b>; üç parkur, kaymalar, Yolcu işaretleri ve Koç Skip'in kıyafetiyle; beş yeni <b>yalnızca Avcı'ya özel yaratık</b> her biri kendi etkisi olan bir zırh takımı düşürür (diken, inanç, gizlilik, ateşe dayanıklılık, mühür tasarrufu); <b>ağır silahlar</b> Güç ister ve onunla daha sert savrulur; <b>Kalp Muhafızı</b>, her on Can seviyesinde bir parçası kazanılan kırmızı-beyaz bir zırhtır; <b>Dawnhold</b>'un köşe kuleli bir kalesi ve daha yüksek bir şapeli var; her sunakta sakallı <b>Old Friend</b>'in heykeli var; görev günlüğü gruplanıp renklendirildi, kemikler bitene dek kendiliğinden sunulur ve Şafak Nöbeti'nin <b>kemik torbası</b> altmış kemik alır.",
    "El continente es ahora el corazón de un mundo cuatro veces mayor, sin tocarlo: <b>el Deadwood</b> y Gravesend al norte, <b>Westmarch y el Drakespine</b> al oeste con <b>Ashfall</b>, el país de los dragones, al final de la península, <b>Southshore</b>, Hollyhock y Dyemoor al sur, <b>Ironreach</b>, Cragmaw, las Tierras Salvajes y Quillhaven al este, y las Islas Pálidas en el mar. Siete aldeas con su propia ropa y sus propias misiones, cuatro mazmorras subterráneas ocultas, veinte temas nuevos. Dos habilidades nuevas: <b>Boticario</b> (hierbas por ecosistema, pociones, venenos que importan, antídotos y nueve mezclas para Friends) y <b>Presencia</b> (un perfil de personaje: pon nombre a tu Friend, funda una hermandad, gana títulos y reputación). Antes, ese mismo mes: Andanzas, las criaturas del Guardián, el Guardacorazón y la torre de Dawnhold. <b>La Agilidad ahora es Andanzas</b>, con tres circuitos, resbalones, marcas de Andante y el atuendo del Entrenador Skip; cinco nuevas <b>criaturas solo para Cazadores</b> sueltan cada una un conjunto de armadura con su propio efecto (espinas, fe, sigilo, resistencia al fuego, ahorro de sigilos); las <b>armas pesadas</b> usan Fuerza y golpean más fuerte con ella; el <b>Guardacorazón</b> es una armadura roja y blanca que se gana pieza a pieza cada diez niveles de Vida; <b>Dawnhold</b> tiene una torre del homenaje con torres en las esquinas y una capilla más alta; cada altar tiene una estatua del barbudo <b>Viejo Amigo</b>; el diario de misiones está agrupado y coloreado, los huesos se ofrecen solos hasta que se acaban, y la <b>bolsa osario</b> de la Vigilia del Alba guarda sesenta.",
    "O continente agora é o coração de um mundo quatro vezes maior, sem ser mexido: <b>Deadwood</b> e Gravesend ao norte, <b>Westmarch e o Drakespine</b> a oeste com <b>Ashfall</b>, o país dos dragões, na ponta da península, <b>Southshore</b>, Hollyhock e Dyemoor ao sul, <b>Ironreach</b>, Cragmaw, as Terras Selvagens e Quillhaven a leste, e as Ilhas Pálidas no mar. Sete vilas com roupas e missões próprias, quatro masmorras subterrâneas escondidas, vinte músicas novas. Duas novas habilidades: <b>Boticário</b> (ervas por ecossistema, poções, venenos que fazem diferença, antídotos e nove misturas para Friends) e <b>Presença</b> (um perfil de personagem: dê nome ao seu Friend, funde uma irmandade, conquiste títulos e reputação). Antes disso, no mesmo mês: Andanças, as criaturas do Guardião, o Guarda-coração e a torre de Dawnhold. <b>Agilidade agora é Andanças</b>, com três percursos, escorregões, marcas de Andarilho e a roupa do Treinador Skip; cinco novas <b>criaturas só para Caçadores</b> derrubam cada uma um conjunto de armadura com efeito próprio (espinhos, fé, furtividade, proteção contra fogo, economia de sigilos); <b>armas pesadas</b> usam Força e batem mais forte com ela; o <b>Guarda-coração</b> é uma armadura vermelha e branca conquistada peça por peça a cada dez níveis de Vida; <b>Dawnhold</b> tem uma torre de menagem com torres nos cantos e uma capela mais alta; todo altar tem uma estátua do barbudo <b>Velho Amigo</b>; o diário de missões está agrupado e colorido, os ossos se oferecem sozinhos até acabarem, e a <b>bolsa ossuária</b> da Vigília da Aurora guarda sessenta deles.",
    "Материк теперь — сердце мира вчетверо больше, а сам остался нетронутым: на севере <b>Deadwood</b> и Грейвсенд, на западе <b>Westmarch и Драконий хребет (Drakespine)</b>, на конце полуострова <b>Эшфолл</b>, страна драконов, на юге <b>Southshore</b>, Холлихок и Даймур, на востоке <b>Ironreach</b>, Крэгмо, The Wilds и Квиллхейвен, в море — Pale Isles. Семь деревень со своей одеждой и своими заданиями, четыре скрытых подземелья, двадцать новых мелодий. Два новых навыка: <b>Аптекарство</b> (травы по экосистемам, зелья, яды, которые имеют значение, противоядия и девять смесей для Friend) и <b>Слава</b> (профиль персонажа: дайте имя своему Friend, основайте братство, зарабатывайте титулы и репутацию). До этого, в том же месяце: Странствия, твари Стража, Страж сердца и донжон Даунхолда. <b>Ловкость теперь — Странствия</b>: три трассы, оскальзывания, знаки странника и наряд тренера Скипа; пять новых <b>тварей только для истребителей</b>, каждая роняет комплект брони со своим эффектом (шипы, вера, скрытность, огнеупорность, экономия печатей); <b>тяжёлое оружие</b> требует силы и бьёт ею сильнее; <b>Страж сердца</b> — красно-белая броня, по части за каждые десять уровней здоровья; в <b>Даунхолде</b> появился донжон с угловыми башнями и более высокая часовня; на каждом алтаре стоит статуя бородатого <b>Old Friend</b>; журнал заданий сгруппирован и раскрашен, кости приносятся сами, пока не кончатся, а в <b>мешок для костей</b> Бдения Рассвета их влезает шестьдесят.",
    "Материк тепер — серце світу вчетверо більшого, а сам лишився недоторканим: на півночі <b>Deadwood</b> і Грейвсенд, на заході <b>Westmarch і Драконячий хребет (Drakespine)</b>, на кінці півострова <b>Ешфолл</b>, країна драконів, на півдні <b>Southshore</b>, Голлігок і Даймур, на сході <b>Ironreach</b>, Крегмо, The Wilds і Квіллгейвен, у морі — Pale Isles. Сім сіл із власним одягом і власними завданнями, чотири приховані підземелля, двадцять нових мелодій. Дві нові навички: <b>Аптекарство</b> (трави за екосистемами, зілля, отрути, що мають значення, протиотрути й дев'ять сумішей для Friend) і <b>Слава</b> (профіль персонажа: дайте ім'я своєму Friend, заснуйте братство, здобувайте титули й репутацію). До цього, того ж місяця: Мандри, потвори Вартового, Страж серця й донжон Даунголда. <b>Спритність тепер — Мандри</b>: три траси, послизання, знаки мандрівника й убрання тренера Скіпа; п'ять нових <b>потвор лише для винищувачів</b>, кожна скидає комплект броні з власним ефектом (шипи, віра, скритність, вогнетривкість, ощадження печаток); <b>важка зброя</b> потребує сили й б'є нею сильніше; <b>Страж серця</b> — червоно-біла броня, по частині за кожні десять рівнів здоров'я; у <b>Даунголді</b> з'явився донжон із кутовими вежами й вища каплиця; на кожному вівтарі стоїть статуя бородатого <b>Old Friend</b>; журнал завдань згруповано й розфарбовано, кістки приносяться самі, доки не скінчаться, а в <b>мішок для кісток</b> Чування Світанку їх уміщається шістдесят.",
  ],
  "Before that: real light, and the Order of the Dawn": ["その前は: 本物の光と暁の教団", "그 전에는: 진짜 빛과 여명 기사단", "在那之前：真实光影，以及黎明骑士团", "在那之前：真實光影，以及黎明騎士團", "Trước đó: ánh sáng thật, và Dòng Bình Minh", "Sebelumnya: cahaya sungguhan, dan Ordo Fajar", "ก่อนหน้านั้น: แสงจริง และภาคีรุ่งอรุณ", "Ondan önce: gerçek ışık ve Order of the Dawn", "Antes de eso: luz real y la Orden del Alba", "Antes disso: luz de verdade e a Ordem da Aurora", "До этого: настоящий свет и Order of the Dawn", "До цього: справжнє світло й Order of the Dawn"],
  "The Realm is lit for real now. The sun crosses the sky and everything casts a shadow that follows it, long and golden at dusk, short at noon, faint under the moon. Lamps, torches, fires, forges and spells light the ground and whatever stands near them, walls and trees block their light, and it bounces softly round corners. Alleys and forest floors sit in soft shade, lava glows and dungeons are truly dark. The Faith update brings the Order of the Dawn: five quests, faith weapons and gold Dawnplate you can see on your Friend. And the townsfolk dress up.": [
    "レルムは今、本物の光に照らされています。太陽が空を渡り、あらゆるものがそれを追う影を落とします。夕暮れには長く金色に、正午には短く、月の下ではかすかに。ランプ、たいまつ、たき火、炉、呪文が地面とそばにあるものを照らし、壁や木々がその光をさえぎり、光は角のまわりでやわらかく跳ね返ります。路地や森の地面はやわらかな陰に沈み、溶岩は輝き、ダンジョンは本当に暗い。信仰アップデートで暁の教団が登場しました。クエスト五つ、信仰の武器、そしてフレンドに見える金の暁鎧。町の人々もおしゃれをしています。",
    "이제 렐름은 진짜 빛으로 밝혀집니다. 해가 하늘을 가로지르고 모든 것이 그 해를 따라가는 그림자를 드리웁니다. 황혼에는 길고 금빛으로, 정오에는 짧게, 달 아래에서는 희미하게. 등불, 횃불, 모닥불, 용광로, 주문이 땅과 그 곁에 선 것들을 비추고, 벽과 나무가 빛을 가리며, 빛은 모퉁이를 돌아 부드럽게 튕겨 나갑니다. 골목과 숲 바닥은 부드러운 그늘에 잠기고, 용암은 빛나며, 던전은 정말로 어둡습니다. 신앙 업데이트로 여명 기사단이 찾아왔습니다. 퀘스트 다섯, 신앙 무기, 그리고 친구에게 보이는 황금 여명판금. 마을 사람들도 차려입었습니다.",
    "王国现在有了真实的光照。太阳横越天空，万物都投下追随它的影子：黄昏时金黄而修长，正午时短小，月光下淡淡的。灯、火炬、篝火、熔炉和法术照亮地面和身旁的一切，墙壁和树木会遮挡光线，光还会在拐角处柔和地反弹。小巷和林地笼罩在柔和的阴影中，熔岩发着光，地下城真正黑暗。信仰更新带来了黎明骑士团：五个任务、信仰武器，以及能在你的伙伴身上看到的金色晨甲。镇民们也换上了新装。",
    "王國現在有了真實的光照。太陽橫越天空，萬物都投下追隨它的影子：黃昏時金黃而修長，正午時短小，月光下淡淡的。燈、火炬、篝火、熔爐和法術照亮地面和身旁的一切，牆壁和樹木會遮擋光線，光還會在轉角處柔和地反彈。小巷和林地籠罩在柔和的陰影中，熔岩發著光，地下城真正黑暗。信仰更新帶來了黎明騎士團：五個任務、信仰武器，以及能在你的夥伴身上看到的金色晨甲。鎮民們也換上了新裝。",
    "Giờ đây Vương quốc được chiếu sáng thật sự. Mặt trời đi ngang bầu trời và mọi thứ đổ bóng theo nó, dài và vàng óng lúc hoàng hôn, ngắn vào giữa trưa, mờ nhạt dưới trăng. Đèn, đuốc, lửa, lò rèn và phép thuật chiếu sáng mặt đất và những gì đứng gần, tường và cây cối chắn sáng, và ánh sáng dội nhẹ quanh các góc. Ngõ hẻm và nền rừng chìm trong bóng râm dịu, dung nham rực sáng và ngục tối thật sự tối. Bản cập nhật Đức tin mang đến Dòng Bình Minh: năm nhiệm vụ, vũ khí đức tin và bộ Dawnplate vàng bạn có thể thấy trên Friend của mình. Và dân thị trấn cũng diện đồ đẹp.",
    "Realm kini diterangi sungguhan. Matahari melintasi langit dan segalanya memiliki bayangan yang mengikutinya, panjang dan keemasan saat senja, pendek saat tengah hari, samar di bawah bulan. Lampu, obor, api, tungku, dan mantra menerangi tanah dan apa pun yang ada di dekatnya, dinding dan pohon menghalangi cahayanya, dan cahaya memantul lembut di tikungan. Gang dan lantai hutan berada dalam keteduhan lembut, lava berpendar, dan dungeon benar-benar gelap. Pembaruan Iman menghadirkan Ordo Fajar: lima misi, senjata iman, dan Dawnplate emas yang terlihat pada Friend Anda. Dan warga kota pun berdandan.",
    "ตอนนี้อาณาจักรมีแสงสว่างจริงแล้ว ดวงอาทิตย์เคลื่อนข้ามฟ้าและทุกสิ่งทอดเงาตามมัน ยาวและเป็นสีทองยามสนธยา สั้นยามเที่ยง และจางใต้แสงจันทร์ ตะเกียง คบเพลิง กองไฟ เตาหลอม และคาถาส่องสว่างพื้นดินและสิ่งที่อยู่ใกล้ กำแพงและต้นไม้บังแสง และแสงสะท้อนนุ่มนวลรอบมุม ตรอกและพื้นป่าอยู่ในเงาร่มนุ่ม ลาวาเรืองแสง และดันเจียนมืดจริง ๆ อัปเดตศรัทธานำภาคีรุ่งอรุณ มาให้: ห้าเควสต์ อาวุธศรัทธา และเกราะรุ่งอรุณ สีทองที่มองเห็นได้บน Friend ของคุณ และชาวเมืองก็แต่งตัวกันแล้ว",
    "Diyar artık gerçekten aydınlatılıyor. Güneş gökyüzünü geçer ve her şey onu izleyen bir gölge düşürür: akşam uzun ve altın rengi, öğlen kısa, ay ışığında soluk. Fenerler, meşaleler, ateşler, ocaklar ve büyüler zemini ve yakındaki her şeyi aydınlatır, duvarlar ve ağaçlar ışığı keser, ışık köşelerden yumuşakça yansır. Ara sokaklar ve orman zemini yumuşak bir gölgede kalır, lav parlar ve zindanlar gerçekten karanlıktır. İnanç güncellemesi Order of the Dawn'u getiriyor: beş görev, inanç silahları ve Friend'inizin üzerinde görebileceğiniz altın Dawnplate. Kasaba halkı da süslendi.",
    "Ahora el Reino tiene luz de verdad. El sol cruza el cielo y todo proyecta una sombra que lo sigue: larga y dorada al atardecer, corta a mediodía, tenue bajo la luna. Faroles, antorchas, hogueras, forjas y hechizos iluminan el suelo y lo que tienen cerca, los muros y los árboles tapan su luz, y esta rebota suavemente al doblar las esquinas. Los callejones y el suelo del bosque quedan en una sombra suave, la lava brilla y las mazmorras están oscuras de verdad. La actualización de la Fe trae la Orden del Alba: cinco misiones, armas de fe y Dawnplate dorada que se ve en tu Friend. Y los vecinos se arreglan.",
    "Agora o Reino tem luz de verdade. O sol cruza o céu e tudo projeta uma sombra que o acompanha: longa e dourada ao entardecer, curta ao meio-dia, fraca sob a lua. Lampiões, tochas, fogueiras, forjas e feitiços iluminam o chão e o que estiver perto, paredes e árvores bloqueiam a luz, e ela rebate suavemente pelas esquinas. Becos e o chão da floresta ficam numa sombra suave, a lava brilha e as masmorras são escuras de verdade. A atualização da Fé traz a Ordem da Aurora: cinco missões, armas de fé e Dawnplate dourada que você vê no seu Friend. E os moradores se arrumam.",
    "Теперь Realm освещён по-настоящему. Солнце пересекает небо, и всё отбрасывает тень, которая следует за ним: длинную и золотую на закате, короткую в полдень, бледную под луной. Фонари, факелы, костры, горны и заклинания освещают землю и всё, что стоит рядом, стены и деревья заслоняют их свет, и он мягко огибает углы. Переулки и лесная подстилка лежат в мягкой тени, лава светится, а подземелья по-настоящему темны. Обновление веры приносит Order of the Dawn: пять заданий, оружие веры и золотой Dawnplate, который виден на вашем Friend. А горожане принарядились.",
    "Тепер Realm освітлено по-справжньому. Сонце перетинає небо, і все відкидає тінь, що йде за ним: довгу й золоту на заході, коротку опівдні, бліду під місяцем. Ліхтарі, смолоскипи, вогнища, горна й закляття освітлюють землю та все, що стоїть поруч, стіни й дерева затуляють їхнє світло, і воно м'яко огинає кути. Провулки й лісова підстилка лежать у м'якій тіні, лава світиться, а підземелля по-справжньому темні. Оновлення віри приносить Order of the Dawn: п'ять завдань, зброю віри та золотий Dawnplate, який видно на вашому Friend. А містяни ошатно вбралися.",
  ],
};
export default table;
